// <auto-generated />
using LiveScore.Shared;
namespace LiveScore.WebApi.Features.Notifications
{
    using System.Collections.Generic;
    using System.Threading.Tasks;
    using LiveScore.Features.Matches.Models;
    using Microsoft.AspNetCore.Mvc;

    [Route("api/[controller]")]
    [ApiController]
    public class NotificationController : ControllerBase
    {
        private InstanceFactory instanceFactory;

        public NotificationController(InstanceFactory instanceFactory)
        {
            this.instanceFactory = instanceFactory;
        }

        [HttpPost("PushMatchEvent")]
        public async Task PushMatchEvent(
            int sportId,
            [FromBody]Dictionary<string, MatchPushEvent> pushEvents)
        {
            if (sportId > 0 && pushEvents != null)
            {
                var pushEventHandler = instanceFactory.CreatePushEventHandler(sportId);

                await pushEventHandler.Handle(pushEvents);
            }
        }
    }
}
